import type { ReactElement } from "react";
import { View } from "react-native";
import type { ButtonSlotProps } from "./button.types";
import { buttonVariants } from "./button.variants";

/**
 * A centred wrapper for trailing content that is not an `Icon`.
 *
 * An `Icon` needs no wrapper — it inherits the button's icon size and its
 * variant's colour from the root's `IconDefaultsProvider`.
 */
export function ButtonEndContent({ className, ...props }: ButtonSlotProps): ReactElement {
	return <View className={buttonVariants().endContent({ className })} {...props} />;
}
ButtonEndContent.displayName = "DelacourUI.Button.EndContent";

import type { ReactElement } from "react";
import type { TextProps } from "react-native";
import { Text } from "@registry/ui/text";
import { useButtonPart } from "./button.context";
import { buttonVariants } from "./button.variants";

export type ButtonLabelProps = TextProps & { className?: string };

/**
 * The button's text.
 *
 * Carries its own colour and type scale, read from the button's context: a
 * React Native `View` does not cascade colour to a `Text` descendant, so a
 * colour set on the root would be lost.
 *
 * The class is passed rather than inherited even though the button publishes the
 * same one through `TextClassProvider` — the two agree, and stating it here
 * keeps the label correct if it is ever rendered somewhere the provider is not.
 */
export function ButtonLabel({ className, ...props }: ButtonLabelProps): ReactElement {
	const { variant, size } = useButtonPart("Button.Label");
	return <Text className={buttonVariants({ size, variant }).label({ className })} {...props} />;
}
ButtonLabel.displayName = "DelacourUI.Button.Label";

import type { ReactElement } from "react";
import { View } from "react-native";
import type { ButtonSlotProps } from "./button.types";
import { buttonVariants } from "./button.variants";

/**
 * A centred wrapper for leading content that is not an `Icon`.
 *
 * An `Icon` needs no wrapper — it inherits the button's icon size and its
 * variant's colour from the root's `IconDefaultsProvider`.
 */
export function ButtonStartContent({ className, ...props }: ButtonSlotProps): ReactElement {
	return <View className={buttonVariants().startContent({ className })} {...props} />;
}
ButtonStartContent.displayName = "DelacourUI.Button.StartContent";

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { ButtonSize, ButtonVariant } from "./button.variants";

export type ButtonContextValue = {
	/** Size of the button. */
	size: ButtonSize;
	/** Visual variant of the button. */
	variant: ButtonVariant;
	/** Whether the button is disabled. */
	isDisabled: boolean;
	/** Whether the button has work in flight. */
	isLoading: boolean;
};

const ButtonContext = createContext<ButtonContextValue | null>(null);

/**
 * Supplies the enclosing button's variant, size and state to its subtree.
 *
 * Lives in its own module, importing nothing but `button.variants`, so a
 * component the button itself renders — `Spinner` — can read it without
 * importing `../button`. That import would close a cycle through
 * `button.tsx`, and Metro serves a partially initialised module for a cycle,
 * leaving the context `undefined` at import time.
 */
export function ButtonProvider({ value, children }: { value: ButtonContextValue; children: ReactNode }): ReactElement {
	return <ButtonContext value={value}>{children}</ButtonContext>;
}
ButtonProvider.displayName = "DelacourUI.Button.Provider";

/** The enclosing button's context, or null outside a `<Button>`. */
export function useButtonContext(): ButtonContextValue | null {
	return use(ButtonContext);
}

/**
 * Reads the enclosing button's variant, size and state.
 *
 * Lets a custom child style itself to match without the button having to pass
 * props down through every slot. Throws outside a `<Button>` — use
 * {@link useButtonContext} where the enclosing button is optional.
 */
export function useButton(): ButtonContextValue {
	const context = useButtonContext();
	if (!context) {
		throw new Error("useButton must be called inside a <Button>.");
	}
	return context;
}

/**
 * The enclosing button's context, for a compound part that cannot work without
 * one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useButton}, whose error message names the hook rather
 * than a part.
 */
export function useButtonPart(component: string): ButtonContextValue {
	const context = useButtonContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside a <Button>.`);
	}
	return context;
}

import { Children, isValidElement, type ReactElement, type ReactNode, useMemo } from "react";
import { Icon, IconDefaultsProvider } from "@registry/ui/icon";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { Spinner } from "@registry/ui/spinner";
import { TextClassProvider } from "@registry/ui/text/text.context";
import { type ButtonContextValue, ButtonProvider } from "./button.context";
import {
	BUTTON_FOREGROUND_TOKEN,
	type ButtonLayout,
	type ButtonSize,
	type ButtonSpinnerPlacement,
	type ButtonVariant,
	buttonVariants,
	resolveButtonLayout,
	resolveSpinnerSwapIndex,
} from "./button.variants";
import { ButtonEndContent } from "./button-end-content";
import { ButtonLabel } from "./button-label";
import { ButtonStartContent } from "./button-start-content";

export type ButtonProps = Omit<PressableProps, "busy" | "children" | "disabled" | "pressedOpacity" | "pressedScale"> & {
	variant?: ButtonVariant;
	size?: ButtonSize;
	/** Square footprint for a button whose only content is an icon. */
	isIconOnly?: boolean;
	isDisabled?: boolean;
	/** Work is in flight: a spinner is composed in and presses are blocked. */
	isLoading?: boolean;
	/** Where the spinner sits. `only` replaces the content, keeping the footprint. */
	spinnerPlacement?: ButtonSpinnerPlacement;
	/** Fade the button while loading, the way `isDisabled` does. Off by default. */
	isDimmedWhileLoading?: boolean;
	children?: ReactNode;
};

function ButtonRoot({
	variant = "primary",
	size = "md",
	isIconOnly = false,
	isDisabled = false,
	isLoading = false,
	isDimmedWhileLoading = false,
	spinnerPlacement = "start",
	feedback = "scale",
	accessibilityLabel,
	className,
	children,
	...props
}: ButtonProps): ReactElement {
	const context = useMemo<ButtonContextValue>(
		() => ({ variant, size, isDisabled, isLoading }),
		[variant, size, isDisabled, isLoading]
	);

	const layout = useMemo(
		() => resolveButtonLayout({ isIconOnly, isLoading, spinnerPlacement }),
		[isIconOnly, isLoading, spinnerPlacement]
	);

	const content = useMemo(() => composeContent(children, layout), [children, layout]);

	const slots = buttonVariants({
		isDimmedWhileLoading,
		isDisabled,
		isIconOnly: layout.isIconOnly,
		isLoading,
		size,
		variant,
	});

	// Icons and spinners composed into the button adopt these unless told otherwise.
	const iconClassName = slots.icon();
	const iconDefaults = useMemo(
		() => ({ className: iconClassName, color: BUTTON_FOREGROUND_TOKEN[variant] }),
		[iconClassName, variant]
	);

	const label = accessibilityLabel ?? (layout.isSpinnerOnly ? textOf(children) : undefined);

	return (
		<ButtonProvider value={context}>
			<Pressable
				accessibilityLabel={label}
				accessibilityRole="button"
				busy={isLoading}
				className={slots.root({ className })}
				disabled={isDisabled}
				feedback={feedback}
				{...props}
			>
				<IconDefaultsProvider value={iconDefaults}>
					<TextClassProvider value={slots.label()}>{content}</TextClassProvider>
				</IconDefaultsProvider>
			</Pressable>
		</ButtonProvider>
	);
}

/**
 * Composes the spinner into the button's children.
 *
 * A loading button **replaces** its icon rather than showing both. Adding a
 * spinner alongside would push the label sideways the moment work started and
 * pull it back when it finished; swapping costs no layout at all, because the
 * spinner and the icon are drawn at the same `size-icon-*` token — the button
 * publishes one class and both read it.
 *
 * `start` takes the first icon and `end` the last, so the spinner lands on the
 * side the caller asked for even when the button holds an icon at both ends.
 * With no icon to take, the spinner is inserted instead and the root's own
 * `gap` spaces it off the label.
 *
 * `only` drops the children: the button has already collapsed to a square, so a
 * label would have nowhere to sit.
 *
 * The spinner is emitted bare — it reads its size and colour from the button's
 * context, so nothing is passed here.
 */
function composeContent(children: ReactNode, layout: ButtonLayout): ReactNode {
	if (layout.isSpinnerOnly) return <Spinner />;
	if (layout.spinnerSide === null) return wrapTextChildren(children);

	const items = Children.toArray(wrapTextChildren(children));
	const swapAt = resolveSpinnerSwapIndex(items.map(isIcon), layout.spinnerSide);

	if (swapAt !== null) {
		return items.map((child, index) => (index === swapAt ? <Spinner key="spinner" /> : child));
	}

	return layout.spinnerSide === "start" ? (
		<>
			<Spinner />
			{items}
		</>
	) : (
		<>
			{items}
			<Spinner />
		</>
	);
}

/**
 * Whether a child is an `Icon` the spinner can stand in for.
 *
 * Only a bare `Icon` qualifies. A `Button.StartContent` wraps arbitrary content
 * whose height the button does not know, so replacing one could resize the
 * button — the thing this swap exists to avoid.
 */
function isIcon(child: ReactNode): boolean {
	return isValidElement(child) && child.type === Icon;
}

/**
 * The button's own text, for use as an accessibility label.
 *
 * `spinnerPlacement="only"` takes the label out of the tree, so the name a
 * screen reader was reading has to be carried onto the root instead. Reaches
 * one level into a `Button.Label`; anything more deeply nested needs an
 * explicit `accessibilityLabel`.
 */
function textOf(children: ReactNode): string | undefined {
	const parts: string[] = [];

	for (const child of Children.toArray(children)) {
		if (typeof child === "string" || typeof child === "number") {
			parts.push(String(child));
			continue;
		}
		if (!isValidElement(child) || child.type !== ButtonLabel) continue;
		const nested = (child.props as { children?: ReactNode }).children;
		if (typeof nested === "string" || typeof nested === "number") parts.push(String(nested));
	}

	return parts.length > 0 ? parts.join("") : undefined;
}

/**
 * Wraps bare text children in a `Button.Label`.
 *
 * React Native cannot render a string outside a `<Text>`, so `<Button>Save</Button>`
 * would otherwise crash. Consecutive strings and numbers are collected into a
 * single label rather than one each — `Row {index}` is one piece of text, and
 * wrapping the parts separately would space them apart by the button's gap.
 */
function wrapTextChildren(children: ReactNode): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];
	let run: (string | number)[] = [];

	const flushRun = () => {
		if (run.length === 0) return;
		output.push(<ButtonLabel key={`label-${output.length}`}>{run.join("")}</ButtonLabel>);
		run = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();
		output.push(child);
	}
	flushRun();

	return output;
}

/**
 * A pressable action, composed from parts rather than configured by flags.
 *
 * `variant`, `size` and the button's state reach the sub-components through
 * context, so `Button.Label` picks its own text colour. That indirection is not
 * incidental: a React Native `View` does not cascade colour to a `Text`
 * descendant the way a DOM element would, so a colour set on the root is lost.
 *
 * Plain string or number children are wrapped in a `Button.Label`
 * automatically; pass the compound parts when a layout needs more control.
 *
 * Icons are composed in, not passed as props. Anything in the subtree inherits
 * the button's icon size and its variant's colour, so an `Icon` needs nothing
 * but the glyph — and a `Spinner` needs nothing at all.
 *
 * Text works the same way: the button publishes its label treatment through a
 * `TextClassProvider`, so a bare `<Text>` composed in comes out at the label's
 * colour and type scale without being told to.
 *
 * `isLoading` blocks presses and announces the button as busy, but does not dim
 * it: a spinner already says the press landed. `isDimmedWhileLoading` opts into
 * the faded treatment.
 *
 * A button is a `Pressable`, so `feedback`, `haptic` and the rest are inherited
 * rather than restated here. Only the default differs: `scale`, the spring the
 * rest of the library's controls press with.
 *
 * @example
 * <Button haptic="selection" onPress={next}>
 *   <Button.Label>Continue</Button.Label>
 *   <Icon icon={IconArrowRight} />
 * </Button>
 *
 * @example
 * <Button isLoading={isSaving} onPress={save}>Save</Button>
 *
 * @example
 * <Button accessibilityLabel="Favourite" isIconOnly variant="ghost">
 *   <Icon icon={IconHeart} />
 * </Button>
 */
export const Button = Object.assign(ButtonRoot, {
	/** The button's text. Picks its colour and type scale from the button's variant and size. */
	Label: ButtonLabel,
	/** A centred wrapper for leading content that is not an `Icon`. */
	StartContent: ButtonStartContent,
	/** A centred wrapper for trailing content that is not an `Icon`. */
	EndContent: ButtonEndContent,
	displayName: "DelacourUI.Button",
});

import type { ViewProps } from "react-native";

/**
 * The shape of a button's leading and trailing slots.
 *
 * Shared by `Button.StartContent` and `Button.EndContent`, which are identical
 * apart from where the root places them, so it lives in a leaf rather than in
 * one of the two files arbitrarily.
 */
export type ButtonSlotProps = ViewProps & { className?: string };

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";

export const BUTTON_VARIANTS = [
	"primary",
	"secondary",
	"tertiary",
	"outline",
	"ghost",
	"danger",
	"danger-soft",
] as const;

export const BUTTON_SIZES = ["sm", "md", "lg"] as const;

export const BUTTON_SPINNER_PLACEMENTS = ["start", "end", "only"] as const;

export type ButtonVariant = (typeof BUTTON_VARIANTS)[number];
export type ButtonSize = (typeof BUTTON_SIZES)[number];
export type ButtonSpinnerPlacement = (typeof BUTTON_SPINNER_PLACEMENTS)[number];

/** Theme token whose value gives icons and text their colour on each surface. */
export const BUTTON_FOREGROUND_TOKEN: Record<ButtonVariant, string> = {
	primary: "primary-foreground",
	secondary: "secondary-foreground",
	tertiary: "tertiary-foreground",
	outline: "foreground",
	ghost: "foreground",
	danger: "danger-foreground",
	"danger-soft": "danger-soft-foreground",
};

/**
 * Styling for every part of a button.
 *
 * One slotted `tv()` rather than a call per part, so `size` and `variant` are
 * declared once.
 *
 * A size names tokens rather than raw utilities: `h-button-md` for the height,
 * `text-button-md` for the label, `size-icon-md` for a composed glyph. The
 * values live in `tokens.css`, so a button's icon and the spinner that replaces
 * it resolve to the same edge length by construction rather than by two numbers
 * happening to agree. `cn` has to know these token names — see `lib/cn.ts`. The root holds no `text-*` utility: a React Native `View` does
 * not cascade colour to a `Text` descendant, so label colour lives on the
 * `label` slot and icon colour is resolved from {@link BUTTON_FOREGROUND_TOKEN}.
 *
 * `overflow-hidden` on the root is load-bearing rather than tidiness — a pressed
 * button fades to the edge of its own box.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const buttonVariants = tv({
	slots: {
		root: "flex-row items-center justify-center gap-2 overflow-hidden rounded-lg border border-transparent",
		label: "text-center font-semibold",
		startContent: "items-center justify-center",
		endContent: "items-center justify-center",
		/** Edge length an `Icon` or `Spinner` composed into the button inherits. */
		icon: "",
	},
	variants: {
		variant: {
			primary: { root: "bg-primary", label: "text-primary-foreground" },
			secondary: { root: "bg-secondary", label: "text-secondary-foreground" },
			tertiary: { root: "bg-tertiary", label: "text-tertiary-foreground" },
			outline: { root: "border-border bg-transparent", label: "text-foreground" },
			ghost: { root: "border-transparent bg-transparent", label: "text-foreground" },
			danger: { root: "bg-danger", label: "text-danger-foreground" },
			"danger-soft": { root: "bg-danger-soft", label: "text-danger-soft-foreground" },
		},
		size: {
			sm: { root: "h-button-sm gap-1.5 rounded-md", label: "text-button-sm", icon: "size-icon-sm" },
			md: { root: "h-button-md", label: "text-button-md", icon: "size-icon-md" },
			lg: { root: "h-button-lg", label: "text-button-lg", icon: "size-icon-lg" },
		},
		// The empty `false` branches are load-bearing typing, not placeholders.
		// `tv` derives the prop type from the declared keys, so a map with only
		// `true` types the prop as `true` rather than `boolean` and rejects
		// `buttonVariants({ isIconOnly: layout.isIconOnly })`. The compound
		// variants below would match without them — `tv` compares against
		// `defaultVariants` plus props and never reads this map.
		isIconOnly: { true: {}, false: {} },
		isDisabled: { true: { root: "opacity-50" }, false: {} },
		isLoading: { true: {}, false: {} },
		isDimmedWhileLoading: { true: {}, false: {} },
	},
	compoundVariants: [
		// A square footprint replaces horizontal padding entirely, so the two
		// are declared together rather than fighting each other in the merge.
		{ isIconOnly: true, size: "sm", class: { root: "w-button-sm" } },
		{ isIconOnly: true, size: "md", class: { root: "w-button-md" } },
		{ isIconOnly: true, size: "lg", class: { root: "w-button-lg" } },
		{ isIconOnly: false, size: "sm", class: { root: "px-3" } },
		{ isIconOnly: false, size: "md", class: { root: "px-4" } },
		{ isIconOnly: false, size: "lg", class: { root: "px-5" } },
		// Loading is not a disabled state. The button keeps full contrast — the
		// spinner already says the press landed — unless the caller opts in.
		{ isLoading: true, isDimmedWhileLoading: true, class: { root: "opacity-50" } },
	],
	defaultVariants: {
		variant: "primary",
		size: "md",
		isIconOnly: false,
		isDisabled: false,
		isLoading: false,
		isDimmedWhileLoading: false,
	},
});

/** Layout facts for a button, once loading state and spinner placement are folded together. */
export type ButtonLayout = {
	/** Square footprint. Loading never turns this on by itself. */
	isIconOnly: boolean;
	/** The spinner has replaced the children entirely. */
	isSpinnerOnly: boolean;
	/** Side the spinner is composed onto, or null when no spinner is shown. */
	spinnerSide: "start" | "end" | null;
};

/**
 * Folds `isLoading` and `spinnerPlacement` into the facts the root needs.
 *
 * `only` swaps the content out but leaves the footprint alone — it never squares
 * a button the caller did not already mark `isIconOnly`. Taking a fixed width
 * here would defeat the parent's `alignItems: stretch`, and a stretch-aligned
 * child with a definite cross size resolves to cross-*start*: a full-width
 * button would snap to a small box flush against the left edge the moment it
 * started loading. Pair `only` with `isIconOnly` when a square is wanted.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveButtonLayout({
	isIconOnly = false,
	isLoading = false,
	spinnerPlacement = "start",
}: {
	isIconOnly?: boolean;
	isLoading?: boolean;
	spinnerPlacement?: ButtonSpinnerPlacement;
}): ButtonLayout {
	if (!isLoading) return { isIconOnly, isSpinnerOnly: false, spinnerSide: null };
	if (spinnerPlacement === "only") return { isIconOnly, isSpinnerOnly: true, spinnerSide: null };
	return { isIconOnly, isSpinnerOnly: false, spinnerSide: spinnerPlacement };
}

/**
 * Index of the child the spinner should replace, or null to insert one.
 *
 * A loading button swaps its icon for the spinner rather than showing both.
 * Adding one would push the label sideways the moment work started and pull it
 * back when it finished — and with the spinner and the icon drawn at the same
 * `size-icon-*` token, replacing costs no layout at all.
 *
 * `start` takes the first icon and `end` the last, so the spinner lands on the
 * side the caller asked for even when the button holds an icon at both ends.
 * With no icon to take there is nothing to swap and the caller gets the
 * inserted spinner the button has always shown.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveSpinnerSwapIndex(isIcon: readonly boolean[], side: "start" | "end"): number | null {
	const index = side === "start" ? isIcon.indexOf(true) : isIcon.lastIndexOf(true);
	return index === -1 ? null : index;
}

export type ButtonVariantProps = VariantProps<typeof buttonVariants>;

export { Button, type ButtonProps } from "./button";
export { type ButtonContextValue, ButtonProvider, useButton, useButtonContext } from "./button.context";
export type { ButtonSlotProps } from "./button.types";
export {
	BUTTON_FOREGROUND_TOKEN,
	BUTTON_SIZES,
	BUTTON_SPINNER_PLACEMENTS,
	BUTTON_VARIANTS,
	type ButtonLayout,
	type ButtonSize,
	type ButtonSpinnerPlacement,
	type ButtonVariant,
	type ButtonVariantProps,
	buttonVariants,
	resolveButtonLayout,
} from "./button.variants";
export type { ButtonLabelProps } from "./button-label";
